  run.inst={};
  if(q){const t=new TextDecoder().decode(await zip.get(q.name));const m=t.match(/\[instrument\]\s*\n([^\n]+)\n([^\n]+)/);
    if(m){const k=m[1].trim().split("\t"),v=m[2].trim().split("\t");k.forEach((kk,i)=>run.inst[kk]=v[i])}}

