function qsHeader(r,opt){
  const e=r.exp,p=e.props||{},I=qsInstrument(r),start=e.runStart||Date.now(),cal=n=>r.calibrations.find(c=>c.name===n)||{};
  const expired=c=>c&&c.exp?(c.exp<start?"Yes":"No"):"";
