  const out=[],re=/name="Time">(\d+)<\/prop>\s*<prop name="Temp">\$?([0-9A-Fa-f.]+)<\/prop>\s*<prop name="Channel">(\d+)<\/prop>\s*<prop name="IntgrTime">(\d+)<\/prop>\s*<prop name="Valid">(\d+)<\/prop>\s*<prop name="RefValue">\$?([0-9A-Fa-f.]+)</g;
