    return {y,cl:p,ucl:Math.min(1,p+e),lcl:Math.max(0,p-e),flags:Number.isFinite(y)&&ni>0&&(p===0?b>0:y>p+e)?[p===0?"event after zero-event baseline":"above p limit"]:[]};})};
