heatColour.code:
function heatColour(value,lo,hi){
  if(!Number.isFinite(value))return "#f8fafc";
  const t=hi>lo?Math.max(0,Math.min(1,(value-lo)/(hi-lo))):0.5;
  const r=Math.round(222+28*t),g=Math.round(245-83*t),b=Math.round(255-103*t);
  return `rgb(${r},${g},${b})`;
}

hexBEToDouble.code:
function hexBEToDouble(hex){
  if(!/^[0-9A-Fa-f]{16}$/.test(hex||""))return null;
  const b=new ArrayBuffer(8),dv=new DataView(b);
  dv.setUint32(0,parseInt(hex.slice(0,8),16),false);
  dv.setUint32(4,parseInt(hex.slice(8),16),false);
  const n=dv.getFloat64(0,false);
  return Number.isFinite(n)?n:null;
}

