function mgViewGraphs(){
  const out=[];
  if(!RUNS.length)return [mgIt({kind:"graph",sev:"none",pict:MG_PICT.graph,kindWord:"graphs",code:"G",
    title:"No run to draw",value:"0",unit:"runs",
