    state:g.note||"",evidence:`graph ${i+1} of ${GRAPHS.length} · drawn with ${SOP.name} v${SOP.version}`,
    graphId:g.id,runIndex:ri,
    rows:[["Group",g.group],["Drawn from",g.scope==="run"?"one run":"every loaded run"],
