}

resultAnswers.code:
function resultAnswers(w){
  if(resultCq(w)!==null)return "cq";
  if(w&&w.undetermined===true)return "undetermined";
  /* a genotype call and a melting temperature are answers in their own modules */
  if(w&&(w.kind==="genotype"||w.kind==="tm")&&((w.call&&String(w.call).trim())||Number.isFinite(Number(w.tm))))return "call";
  const st=`${(w&&w.CpState)||""} ${(w&&w.CrossingPointStatus)||""} ${(w&&w.call)||""}`;
  if(CQ_NEGATIVE_STATUS.test(st))return "undetermined";
  return "";
}

resultCq.code:
function resultCq(w){
  for(const v of [w&&w.CpRaw,w&&w.Cq,w&&w.Ct,w&&w.cq,w&&w.ct]){
    if(v===null||v===undefined||v==="")continue;
    const n=Number(v);if(Number.isFinite(n)&&n>0)return n;}
  return null;
}

resultKindOf.code:
function resultKindOf(d,lists){
  if("CrossingPoint" in d)return "quant";
  if("TargetCpMedian" in d||"NormRatio" in d||"ConcRatio" in d)return "relquant";
  /* Gene Scanning and Melt Curve Genotype records also contain TmCount and Tms
     placeholders. Roche's LIMS guide distinguishes them by GroupName / Res /
     Score, so classify those fields before the Tm Calling fields. */
  if("PeakWtFluor" in d||"PeakMutFluor" in d||"Score" in d)return "genotype";
  if("GroupName" in d||"Res" in d)return "genotype";
  if("TmCount" in d||(lists.Tms&&lists.Tms.length))return "tm";
  return "other";
}

